const http = require('node:http');
const { randomBytes, createHash, scrypt, timingSafeEqual } = require('node:crypto');
const { promisify } = require('node:util');
const { gunzipSync } = require('node:zlib');
const files = JSON.parse(gunzipSync(Buffer.from('', 'base64')));
const port = Number(process.env.PORT || 10000);
const origin = process.env.RENDER_EXTERNAL_URL || process.env.PUBLIC_ORIGIN || 'http://localhost:' + port;
const backend = process.env.RUVI_BACKEND_URL;
const key = process.env.RUVI_RENDER_DRIVER_KEY;
const fixedCountry = process.env.RUVI_REGISTRATION_COUNTRY;
if (fixedCountry && !['VE', 'DO'].includes(fixedCountry)) {
  throw new Error('Invalid RUVI_REGISTRATION_COUNTRY');
}
const cookieName = '__Host-ruvi_driver';
const hash = text => createHash('sha256').update(text).digest('hex');
const derive = promisify(scrypt);
let hashing = false;

async function bridge(payload) {
  const response = await fetch(backend + '/api/ruvi/render-driver', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
    signal: AbortSignal.timeout(13000),
  });
  const data = await response.json();
  return { status: response.status, data };
}
function send(response, status, content, headers = {}) {
  response.writeHead(status, {
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'same-origin',
    'X-Frame-Options': 'DENY',
    ...headers,
  });
  response.end(content);
}
function json(response, status, data) {
  send(response, status, JSON.stringify(data), { 'Content-Type': 'application/json' });
}
async function readBody(request, limit = 12000) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > limit) throw new Error('body');
  }
  return body;
}
function sessionHash(request) {
  const token = (request.headers.cookie ?? '').split(';').map(value => value.trim())
    .find(value => value.startsWith(cookieName + '='))?.slice(cookieName.length + 1);
  return typeof token === 'string' && /^[a-f0-9]{64}$/.test(token) ? hash(token) : undefined;
}
function sessionCookie(token, maxAge = 604800) {
  return cookieName + '=' + token + '; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=' + maxAge;
}
function safeNext(value) {
  const [pathname, query] = (typeof value === 'string' ? value : '/').split('?');
  if (!['/negocios/', '/conductores/', '/vendedores/'].includes(pathname)) return '/';
  const country = fixedCountry || new URLSearchParams(query).get('pais');
  return pathname + (["VE", "DO", "US", "ES", "PT", "FR", "IT", "DE", "NL", "BE", "GB", "IE", "CH", "AT", "SE", "NO", "DK", "FI", "PL", "CZ", "GR", "RO", "HU", "BG", "HR", "SK", "SI", "EE", "LV", "LT", "LU", "MT", "CY", "IS", "AL", "AD", "BA", "LI", "MC", "ME", "MK", "RS", "SM", "VA", "MD", "UA", "BY"].includes(country) ? '?pais=' + country : '');
}
function accountPage(response, message = '', next = '/') {
  const html = Buffer.from(files['/cuenta/index.html'].body, 'base64').toString()
    .replace('<!--MESSAGE-->', message ? '<p role="alert">' + message + '</p>' : '')
    .replaceAll('<!--NEXT-->', safeNext(next))
    .replace('<!--DESTINATION-->', safeNext(next).startsWith('/conductores/') ? 'driver' : 'general');
  send(response, 200, html, { 'Content-Type': 'text/html; charset=utf-8' });
}
async function passwordKey(password, salt) {
  return derive(password, Buffer.from(salt, 'hex'), 64, { N: 131072, r: 8, p: 1, maxmem: 192 * 1024 * 1024 });
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, origin);
    if(request.method === 'GET' && ['/marketplace','/marketplace/'].includes(url.pathname) && url.searchParams.get('catalogo') !== 'legacy') {
      send(response,302,'',{Location:'https://ruviconecta.com/marketplace/'}); return;
    }
    if (request.method === 'GET' && url.pathname === '/health') {
      json(response, key && backend ? 200 : 503, { ready: Boolean(key && backend) });
      return;
    }
    if (request.method === 'GET' && url.pathname === '/cuenta/') {
      const destination = ({negocios:'/negocios/',conductores:'/conductores/',vendedores:'/vendedores/'})[url.searchParams.get('destino')] ?? '/';
      const country = fixedCountry || url.searchParams.get('pais');
      accountPage(response, '', destination + (["VE", "DO", "US", "ES", "PT", "FR", "IT", "DE", "NL", "BE", "GB", "IE", "CH", "AT", "SE", "NO", "DK", "FI", "PL", "CZ", "GR", "RO", "HU", "BG", "HR", "SK", "SI", "EE", "LV", "LT", "LU", "MT", "CY", "IS", "AL", "AD", "BA", "LI", "MC", "ME", "MK", "RS", "SM", "VA", "MD", "UA", "BY"].includes(country) ? '?pais=' + country : ''));
      return;
    }
    if (request.method === 'POST') {
      if (request.headers.origin !== origin) { json(response, 403, { error: 'invalid' }); return; }
      const tokenHash = sessionHash(request);
      if (url.pathname === '/auth/logout') {
        const result = await bridge({ operation: 'logout', tokenHash });
        if (result.status !== 200) { json(response, result.status, result.data); return; }
        send(response, 303, '', { Location: '/', 'Set-Cookie': sessionCookie('', 0) });
        return;
      }
      if (['/auth/signup', '/auth/login'].includes(url.pathname)) {
        if (!request.headers['content-type']?.startsWith('application/x-www-form-urlencoded')) {
          json(response, 415, { error: 'invalid' }); return;
        }
        const data = new URLSearchParams(await readBody(request));
        const email = (data.get('email') ?? '').trim().toLowerCase();
        const password = data.get('password') ?? '';
        const next = safeNext(data.get('next'));
        const accountError = message => accountPage(response, message, next);
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254 || password.length < 15 || password.length > 128) {
          accountError('Escribe un correo válido y una contraseña de 15 a 128 caracteres.'); return;
        }
        if (hashing) { accountError('Hay otra solicitud en curso. Reintenta en unos segundos.'); return; }
        hashing = true;
        try {
          const gate = await bridge({ operation: 'gate', key: hash(email) });
          if (gate.status !== 200) {
            accountError(gate.status === 429 ? 'Demasiados intentos. Espera 15 minutos y reintenta.' : 'No pudimos conectar con RUVI. Reintenta.');
            return;
          }
          let accountId;
          if (url.pathname === '/auth/signup') {
            const salt = randomBytes(16).toString('hex');
            const passwordHash = 'scrypt:' + salt + ':' + (await passwordKey(password, salt)).toString('hex');
            const result = await bridge({ operation: 'signup', email, passwordHash });
            if (result.status !== 201) {
              accountError(result.data.error === 'account_exists' ? 'Ese correo ya tiene una cuenta. Usa Iniciar sesión.' : 'No pudimos crear la cuenta. Reintenta.');
              return;
            }
            accountId = result.data.id;
          } else {
            const result = await bridge({ operation: 'lookup', email });
            if (result.status !== 200) { accountError('No pudimos conectar con RUVI. Reintenta.'); return; }
            const stored = result.data.account?.password_hash;
            const parts = stored?.split(':');
            const actual = await passwordKey(password, parts?.[1] ?? '00000000000000000000000000000000');
            const expected = parts?.[2] ? Buffer.from(parts[2], 'hex') : Buffer.alloc(64);
            if (!stored || expected.length !== actual.length || !timingSafeEqual(actual, expected)) {
              accountError('El correo o la contraseña no coinciden.'); return;
            }
            accountId = result.data.account.id;
          }
          const token = randomBytes(32).toString('hex');
          const session = await bridge({ operation: 'session', accountId, tokenHash: hash(token) });
          if (session.status !== 200) { accountError('Tu cuenta está guardada. Vuelve a iniciar sesión.'); return; }
          send(response, 303, '', { Location: next, 'Set-Cookie': sessionCookie(token) });
        } finally { hashing = false; }
        return;
      }
    }
    if (url.pathname.startsWith('/api/ruvi/') && ['GET', 'POST'].includes(request.method)) {
      const payload = request.method === 'POST' ? JSON.parse(await readBody(request, 160000)) : undefined;
      if (fixedCountry && request.method === 'POST' && url.pathname === '/api/ruvi/driver/profile'
        && payload?.country !== fixedCountry) {
        json(response, 400, { error: 'invalid' }); return;
      }
      const result = await bridge({ operation: 'api', endpoint: url.pathname.slice('/api/ruvi/'.length) + url.search,
        tokenHash: sessionHash(request), payload });
      json(response, result.status, result.data);
      return;
    }
    if (!['GET', 'HEAD'].includes(request.method)) { json(response, 405, { error: 'invalid' }); return; }
    const menuPath = /^\/menu\/[0-9a-f-]{36}\/$/i.test(url.pathname);
    const assetPath = menuPath ? '/menu/index.html' : url.pathname.endsWith('/') ? url.pathname + 'index.html' : url.pathname;
    const asset = files[assetPath];
    if (!asset) { send(response, 404, 'Página no encontrada'); return; }
    let body = Buffer.from(asset.body, 'base64');
    if (fixedCountry && asset.type.startsWith('text/html')) {
      body = body.toString().replace(/<html\b[^>]*>/, tag =>
        tag.replace(/ data-registration-country="[^"]*"/, '').slice(0, -1)
          + ' data-registration-country="' + fixedCountry + '" data-fixed-country="' + fixedCountry + '">');
    }
    send(response, 200, request.method === 'HEAD' ? '' : body, { 'Content-Type': asset.type });
  } catch (error) {
    console.error('RUVI request failed:', error.name);
    json(response, error instanceof SyntaxError ? 400 : 503, { error: 'unavailable' });
  }
});
server.listen(port, '0.0.0.0');
process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 25000).unref();
});
